BehaviorModuleOutput BidirectionalTrafficModule::plan()
{
  using autoware_internal_planning_msgs::msg::PathPointWithLaneId;

  BehaviorModuleOutput module_output = getPreviousModuleOutput();

  PathWithLaneId previous_path = module_output.path;

  auto trajectory = experimental::trajectory::Trajectory<
                      autoware_internal_planning_msgs::msg::PathPointWithLaneId>::Builder{}
                      .build(previous_path.points);

  if (!trajectory) {
    RCLCPP_ERROR(getLogger(), "Failed to build trajectory in BidirectionalTrafficModule::plan");
    return module_output;
  }

  *trajectory = shift_trajectory_for_keep_left(
    *trajectory, get_all_bidirectional_lanes_in_map(), *parameters_,
    EgoParameters::from_planner_data(*planner_data_));

  if (give_way_ && oncoming_cars_) {
    const double speed = planner_data_->self_odometry->twist.twist.linear.x;
    *trajectory = give_way_->modify_trajectory(*trajectory, *oncoming_cars_, getEgoPose(), speed);
  }

  module_output.path.points = trajectory->restore();

  return module_output;
}

shift_trajectory_for_keep_left(
  const experimental::trajectory::Trajectory<
    autoware_internal_planning_msgs::msg::PathPointWithLaneId> & trajectory,
  const std::vector<ConnectedBidirectionalLanelets::SharedConstPtr> &
    all_connected_bidirectional_lanelets,
  const BidirectionalTrafficModuleParameters & parameter, const EgoParameters & ego_params,
  const std::function<void(std::string_view)> & logger)
{
  std::vector<experimental::trajectory::ShiftInterval> shifts_for_keep_left;

  for (const ConnectedBidirectionalLanelets::SharedConstPtr & bidirectional_lanelet :
       all_connected_bidirectional_lanelets) {
    // Get the overlap interval between the trajectory and the bidirectional lanelet
    std::optional<experimental::trajectory::Interval> overlap_interval =
      bidirectional_lanelet->get_overlap_interval(trajectory);
    if (!overlap_interval.has_value()) {  // No overlap
      continue;
    }

    const double keep_left_distance = -std::min(
      parameter.keep_left_distance_from_center_line,
      bidirectional_lanelet->average_lane_width() / 2.0 - ego_params.vehicle_width / 2.0 -
        parameter.min_distance_from_roadside);

    // Make a shift for entering the bidirectional lanelet
    lanelet::ConstLanelets lanelets_before_entering_bidirectional_lanelet = filter_lanelets_by_ids(
      bidirectional_lanelet->get_lanelets_before_entering(), trajectory.get_contained_lane_ids());

    double shift_start_s = 0.0;

    if (lanelets_before_entering_bidirectional_lanelet.size() > 1) {
      logger("The trajectory has multiple lanelets before entering the bidirectional lane");
    }
    if (lanelets_before_entering_bidirectional_lanelet.empty()) {
      shift_start_s = std::numeric_limits<double>::lowest();
    } else {
      shift_start_s =
        overlap_interval->start -
        compute_length_of_lanelets(lanelets_before_entering_bidirectional_lanelet.front());
    }
    shifts_for_keep_left.emplace_back(
      experimental::trajectory::ShiftInterval{
        shift_start_s, overlap_interval->start, keep_left_distance});

    lanelet::ConstLanelets lanelets_after_exiting_bidirectional_lanelet = filter_lanelets_by_ids(
      bidirectional_lanelet->get_lanelets_after_exiting(), trajectory.get_contained_lane_ids());

    // experimental::trajectory::ShiftInterval shift_for_exiting_bidirectional_lanelet;
    double shift_end_s = 0.0;

    if (lanelets_after_exiting_bidirectional_lanelet.size() > 1) {
      logger("The trajectory has multiple lanelets after exiting the bidirectional lane");
    }

    if (lanelets_after_exiting_bidirectional_lanelet.empty()) {
      shift_end_s = std::numeric_limits<double>::max();
    } else {
      shift_end_s = overlap_interval->end + compute_length_of_lanelets(
                                              lanelets_after_exiting_bidirectional_lanelet.front());
    }
    shifts_for_keep_left.emplace_back(
      experimental::trajectory::ShiftInterval{
        overlap_interval->end, shift_end_s, -keep_left_distance});
  }

  auto shifted_trajectory =
    experimental::trajectory::shift(trajectory, shifts_for_keep_left, {0.0, 0.0});

  if (!shifted_trajectory) {
    logger(shifted_trajectory.error().what);
    return trajectory;
  }
  return shifted_trajectory.value();
}

ConnectedBidirectionalLanelets::get_overlap_interval(
  const experimental::trajectory::Trajectory<
    autoware_internal_planning_msgs::msg::PathPointWithLaneId> & trajectory) const
{
  std::unordered_set<lanelet::Id> lane_ids_set;
  for (const auto & lanelet : bidirectional_lanelets_) {
    lane_ids_set.insert(lanelet.id());
  }

  auto interval = experimental::trajectory::find_intervals(
    trajectory,
    [&](const autoware_internal_planning_msgs::msg::PathPointWithLaneId & point) -> bool {
      for (const auto & lane_id : point.lane_ids) {
        return lane_ids_set.find(lane_id) != lane_ids_set.end();
      }
      return false;
    });
  if (interval.empty()) return std::nullopt;
  return interval.front();
}

std::vector<Interval> find_intervals(
  const Trajectory<TrajectoryPointType> & trajectory, Constraint && constraint, int max_iter = 0)
{
  return detail::impl::find_intervals_impl(
    trajectory.get_underlying_bases(),
    [constraint = std::forward<Constraint>(constraint), &trajectory](const double & s) {
      return detail::invoke_with_point_or_parameter(
        constraint, s, [&trajectory, &s]() { return trajectory.compute(s); });
    },
    max_iter);
}

std::vector<Interval> find_intervals_impl(
  const std::vector<double> & bases, const std::function<bool(const double &)> & constraint,
  int max_iter)
{
  std::vector<Interval> intervals;

  double start = -1.0;
  bool is_started = false;

  for (size_t i = 0; i < bases.size(); ++i) {
    if (!is_started && constraint(bases.at(i))) {
      if (i > 0) {
        start = autoware::experimental::trajectory::detail::lower_bound_by_predicate(
          bases.at(i - 1), bases.at(i), constraint, static_cast<size_t>(max_iter));
      } else {
        start = bases.at(i);  // Start a new interval}
      }
      is_started = true;  // Set the flag to indicate the interval has started
    } else if (is_started && !constraint(bases.at(i))) {
      // End the current interval if the constraint fails or it's the last element
      double end = autoware::experimental::trajectory::detail::upper_bound_by_predicate(
        bases.at(i - 1), bases.at(i), constraint, static_cast<size_t>(max_iter));
      intervals.emplace_back(Interval{start, end});
      start = -1.0;        // Reset the start
      is_started = false;  // Reset the flag
    } else if (is_started && i == bases.size() - 1) {
      // If the last element is valid, end the interval
      double end = bases.at(i);
      intervals.emplace_back(Interval{start, end});
      start = -1.0;        // Reset the start
      is_started = false;  // Reset the flag
    }
  }
  return intervals;
}

inline double lower_bound_by_predicate(
  double low, double high, Predicate predicate, size_t max_iter,
  double tolerance = std::numeric_limits<double>::epsilon())
{
  for (size_t i = 0; i < max_iter; ++i) {
    if (high - low <= tolerance) {
      break;
    }

    const double mid = 0.5 * (low + high);
    if (predicate(mid)) {
      high = mid;
    } else {
      low = mid;
    }
  }

  return high;
}

inline double upper_bound_by_predicate(
  double low, double high, Predicate predicate, size_t max_iter,
  double tolerance = std::numeric_limits<double>::epsilon())
{
  for (size_t i = 0; i < max_iter; ++i) {
    if (high - low <= tolerance) {
      break;
    }

    const double mid = 0.5 * (low + high);
    if (predicate(mid)) {
      low = mid;
    } else {
      high = mid;
    }
  }

  return low;
}

std::vector<double> Trajectory<PointType>::get_underlying_bases() const
{
  auto bases = detail::crop_bases(bases_, start_, end_);
  std::transform(
    bases.begin(), bases.end(), bases.begin(), [this](const double s) { return s - start_; });
  return bases;
}

std::vector<double> crop_bases(const std::vector<double> & x, const double start, const double end)
{
  std::vector<double> result;

  // Add start point if it's not already in x
  if (std::find(x.begin(), x.end(), start) == x.end()) {
    result.push_back(start);
  }

  // Copy all points within the range [start, end]
  std::copy_if(x.begin(), x.end(), std::back_inserter(result), [start, end](double i) {
    return i >= start && i <= end;
  });

  // Add end point if it's not already in x
  if (std::find(x.begin(), x.end(), end) == x.end()) {
    result.push_back(end);
  }

  return result;
}

decltype(auto) invoke_with_point_or_parameter(
  Callable & callable, const double & parameter, PointGetter && point_getter)
{
  using PointType = std::decay_t<std::invoke_result_t<PointGetter &>>;

  if constexpr (std::is_invocable_v<Callable &, const PointType &>) {
    return std::invoke(callable, std::invoke(std::forward<PointGetter>(point_getter)));
  } else if constexpr (std::is_invocable_v<Callable &, const double &>) {
    return std::invoke(callable, parameter);
  } else {
    static_assert(
      always_false_v<Callable>,
      "callable must be callable with either the trajectory point type or double");
  }
}

[[nodiscard]] double ConnectedBidirectionalLanelets::average_lane_width() const
{
  static autoware_utils_system::LRUCache<lanelet::ConstLanelets, double, ConstLaneletsHashMap>
    cache(1000);
  if (cache.contains(bidirectional_lanelets_)) {
    return cache.get(bidirectional_lanelets_).value();
  }
  long double length_sum = 0;
  double area_sum = 0;
  for (const auto & lane : bidirectional_lanelets_) {
    length_sum += boost::geometry::length(lane.centerline2d());
    area_sum += boost::geometry::area(lane.polygon2d().basicPolygon());
  }

  auto result = static_cast<double>(area_sum / length_sum);
  cache.put(bidirectional_lanelets_, result);
  return result;
}

lanelet::ConstLanelets filter_lanelets_by_ids(
  const lanelet::ConstLanelets & all_lanelets, const lanelet::Ids & target_lane_ids)
{
  lanelet::ConstLanelets filtered_lanelets;
  std::unordered_set<lanelet::Id> target_lane_ids_set(
    target_lane_ids.begin(), target_lane_ids.end());
  for (const auto & lanelet : all_lanelets) {
    if (target_lane_ids_set.find(lanelet.id()) != target_lane_ids_set.end()) {
      filtered_lanelets.emplace_back(lanelet);
    }
  }
  return filtered_lanelets;
}

ConnectedBidirectionalLanelets::get_lanelets_before_entering() const
{
  return lanelets_before_entering_;
}

double compute_length_of_lanelets(const lanelet::ConstLanelet & lanelet)
{
  static autoware_utils_system::LRUCache<lanelet::Id, double> lanelet_length_cache(1000);
  if (lanelet_length_cache.contains(lanelet.id())) {
    return lanelet_length_cache.get(lanelet.id()).value();
  }
  double length = lanelet::geometry::length3d(lanelet);
  lanelet_length_cache.put(lanelet.id(), length);
  return length;
}

ConnectedBidirectionalLanelets::get_lanelets_after_exiting() const
{
  return lanelets_after_entering_;
}

tl::expected<trajectory::Trajectory<PointType>, ShiftError> shift(
  const trajectory::Trajectory<PointType> & reference_trajectory,
  const std::vector<ShiftInterval> & shift_intervals, const ShiftParameters & shift_parameters)
{
  if (shift_parameters.velocity < 0.0) {
    return tl::unexpected{ShiftError{"Longitudinal velocity must be positive."}};
  }

  detail::ShiftElement shift_element{reference_trajectory.get_underlying_bases()};

  for (const ShiftInterval & shift_interval : shift_intervals) {
    auto try_shift = detail::shift_impl(shift_element, shift_interval, shift_parameters);
    if (!try_shift) {
      return tl::unexpected{try_shift.error()};
    }
    shift_element = std::move(try_shift.value());
  }

  // Apply shift.
  std::vector<PointType> shifted_points;
  shifted_points.reserve(shift_element.lon_bases.size());
  for (const auto [base, shift_length] :
       ranges::views::zip(shift_element.lon_bases, shift_element.lat_shifts)) {
    shifted_points.emplace_back(reference_trajectory.compute(base));
    const double azimuth = reference_trajectory.azimuth(base);
    detail::to_point(shifted_points.back()).x += std::sin(azimuth) * shift_length;
    detail::to_point(shifted_points.back()).y -= std::cos(azimuth) * shift_length;
  }
  auto shifted_trajectory = reference_trajectory;
  const auto valid = shifted_trajectory.build(shifted_points);
  if (!valid) {
    // This Exception is never thrown, because `shifted_bases` contains at least 4 or 7 new bases in
    // addition to reference_bases, which is enough for cubic spline
    return tl::unexpected{ShiftError{"Failed to build cubic spline for shift calculation."}};
  }
  return shifted_trajectory;
}

tl::expected<ShiftElement, ShiftError> shift_impl(
  ShiftElement shift_element, const ShiftInterval & shift_interval,
  const ShiftParameters & shift_parameters)
{
  if (std::max(shift_interval.start, shift_interval.end) <= shift_element.lon_bases.front()) {
    for (auto & lateral_shift : shift_element.lat_shifts) {
      lateral_shift += shift_interval.lateral_offset;
    }
    return shift_element;
  }

  if (std::min(shift_interval.start, shift_interval.end) >= shift_element.lon_bases.back()) {
    return shift_element;
  }

  auto cubic_spline_original = interpolator::CubicSpline::Builder{}
                                 .set_bases(shift_element.lon_bases)
                                 .set_values(shift_element.lat_shifts)
                                 .build();

  if (!cubic_spline_original) {
    return tl::unexpected(ShiftError{"Failed to build cubic spline of original"});
  }

  const double shift_arc_length = std::abs(shift_interval.end - shift_interval.start);
  // Calculate base lengths
  const auto try_calc_base_length = calc_base_lengths(
    shift_arc_length,               //
    shift_interval.lateral_offset,  //
    shift_parameters);
  if (!try_calc_base_length) {
    return tl::unexpected(try_calc_base_length.error());
  }
  // base_lon starts from 0.0
  // NOTE(soblin): calc_base_length may be like [s0, s1, L_lon, L_lon, L_lon], in which case it
  // causes zero division in interpolator
  const auto [base_lon, base_lat] = sanitize_same_base(try_calc_base_length.value());

  auto cubic_spline_shift =
    interpolator::CubicSpline::Builder{}.set_bases(base_lon).set_values(base_lat).build();

  // for above zero division reason, cubic spline may fail
  if (!cubic_spline_shift) {
    std::stringstream ss;
    ss << "Failed to build cubic spline for shift calculation because interval [s0, ... ,s7] "
          "reached L_lon: " +
            cubic_spline_shift.error().what
       << std::endl;
    ss << "L_lon = " << (shift_interval.end - shift_interval.start)
       << ", L = " << shift_interval.lateral_offset << std::endl;
    ss << "v_lon = " << shift_parameters.velocity
       << ", lat_acc_limit = " << shift_parameters.lateral_acc_limit << std::endl;
    return tl::unexpected{ShiftError{ss.str()}};
  }

  std::set<double> merged_bases{shift_element.lon_bases.begin(), shift_element.lon_bases.end()};
  for (const auto new_base : base_lon) {
    merged_bases.insert(new_base + shift_interval.start);
  }

  const auto shift_start_it = merged_bases.find(base_lon.front() + shift_interval.start);
  if (shift_start_it == merged_bases.end()) {
    return tl::unexpected(ShiftError{"could not find shift start base in shift_impl"});
  }
  const auto shift_end_it = merged_bases.find(base_lon.back() + shift_interval.start);
  if (shift_end_it == merged_bases.end()) {
    return tl::unexpected(ShiftError{"could not find shift end base in shift_impl"});
  }

  // Erase elements from merged_bases that are less than shift_element.lon_bases.front() or greater
  // than shift_element.lon_bases.back().
  for (auto it = merged_bases.begin(); it != merged_bases.end();) {
    if (*it < shift_element.lon_bases.front() || *it > shift_element.lon_bases.back()) {
      it = merged_bases.erase(it);  // erase returns the next iterator
    } else {
      ++it;
    }
  }

  std::vector<double> new_bases;
  std::vector<double> shift_values;
  new_bases.reserve(merged_bases.size());
  shift_values.reserve(merged_bases.size());

  for (const auto s : merged_bases) {
    // Calculate the shift length at the current base
    new_bases.push_back(s);
    double original = cubic_spline_original->compute(s);
    if (s < shift_interval.start) {
      // before shifted
      shift_values.push_back(original);
    } else if (s <= shift_interval.end) {
      // middle
      shift_values.push_back(original + cubic_spline_shift->compute(s - shift_interval.start));
    } else {
      // after shifted
      shift_values.push_back(original + cubic_spline_shift->compute(shift_arc_length));
    }
  }

  shift_element.lon_bases = std::move(new_bases);
  shift_element.lat_shifts = std::move(shift_values);

  return shift_element;
}

tl::expected<std::pair<std::vector<double>, std::vector<double>>, ShiftError> calc_base_lengths(
  const double & arc_length, const double & shift_length, const ShiftParameters & shift_parameters)
{
  // Threshold for treating acceleration as zero
  const double acc_threshold = 1.0e-4;

  // Extract initial velocity and clamp negative acceleration to zero
  const double v_0_lon = std::abs(shift_parameters.velocity);
  const double a_lon =
    (shift_parameters.longitudinal_acc > acc_threshold) ? shift_parameters.longitudinal_acc : 0.0;

  // If there is no need to consider acceleration limit
  if (v_0_lon < 1.0e-5 && a_lon < acc_threshold) {
    RCLCPP_DEBUG_THROTTLE(
      get_logger(), get_clock(), 3000,
      "Velocity is effectively zero. "
      "No lateral acceleration limit will be applied.");
    return get_base_lengths_without_accel_limit(arc_length, shift_length);
  }

  // Prepare main parameters
  const double L_lon = arc_length;          // NOLINT
  const double L = std::abs(shift_length);  // NOLINT

  // Calculate total time (total_time) to travel 'target_arclength'
  // If effective_lon_acc is valid (> 0), use time from kinematic formula. Otherwise, use s/v
  const double T_total = (a_lon > acc_threshold)  // NOLINT
                           ? (-v_0_lon + std::sqrt(v_0_lon * v_0_lon + 2.0 * a_lon * L_lon)) / a_lon
                           : (L_lon / v_0_lon);

  // Calculate the maximum lateral acceleration if we do not add further constraints
  const double max_lateral_acc = 8.0 * L / (T_total * T_total);

  // If the max_lateral_acc is already below the limit, no need to reduce it
  const double a_lim_lat = shift_parameters.lateral_acc_limit;
  if (max_lateral_acc < a_lim_lat) {
    RCLCPP_DEBUG_THROTTLE(
      get_logger(), get_clock(), 3000, "No need to consider lateral acc limit. max: %f, limit: %f",
      max_lateral_acc, shift_parameters.lateral_acc_limit);
    return get_base_lengths_without_accel_limit(L_lon, shift_length, v_0_lon, a_lon, T_total);
  }

  // Compute intermediate times (jerk_time / accel_time) and lateral jerk
  const double T_j = T_total / 2.0 - 2.0 * L / (a_lim_lat * T_total);  // NOLINT
  const double T_a = 4.0 * L / (a_lim_lat * T_total) - T_total / 2.0;  // NOLINT
  const double jerk =
    (2.0 * a_lim_lat * a_lim_lat * T_total) / (a_lim_lat * T_total * T_total - 4.0 * L);

  // If computed times or jerk are invalid (negative or too small), skip the acc limit
  if (T_j < 0.0 || T_a < 0.0 || jerk < 0.0) {
    std::stringstream ss;
    ss << "computed maximum lateral acc: " << max_lateral_acc << " (hard limit is " << a_lim_lat
       << ")" << std::endl;
    if (T_j < 0.0) {
      ss << "Infeasible: T_j is negative" << std::endl;
    }
    if (T_a < 0.0) {
      ss << "Infeasible: T_a is negative" << std::endl;
    }
    if (jerk < 0.0) {
      ss << "Infeasible: jerk is negative" << std::endl;
    }
    ss << "(1)Increase the lateral_acc_limit or (2)Decrease shift_length if possible or "
          "(3)Re-check velocity and acceleration settings for consistency"
       << std::endl;
    return tl::unexpected(ShiftError{ss.str()});
  }

  // Precompute powers for jerk_time and accel_time
  const double jerk_time3 = std::pow(T_j, 3);
  const double accel_time2_jerk = std::pow(T_a, 2) * T_j;
  const double accel_time_jerk2 = T_a * std::pow(T_j, 2);

  // ------------------------------------------------------
  // Calculate longitudinal base points
  // ------------------------------------------------------
  // Segment s1
  const double s1 = std::min(T_j * v_0_lon + 0.5 * a_lon * T_j * T_j, L_lon);
  const double v1 = v_0_lon + a_lon * T_j;

  // Segment s2
  const double s2 = std::min(s1 + T_a * v1 + 0.5 * a_lon * T_a * T_a, L_lon);
  const double v2 = v1 + a_lon * T_a;

  // Segment s3 = s4
  const double s3 = std::min(s2 + T_j * v2 + 0.5 * a_lon * T_j * T_j, L_lon);
  const double v3 = v2 + a_lon * T_j;

  // Segment s5
  const double s5 = std::min(s3 + T_j * v3 + 0.5 * a_lon * T_j * T_j, L_lon);
  const double v5 = v3 + a_lon * T_j;

  // Segment s6
  const double s6 = std::min(s5 + T_a * v5 + 0.5 * a_lon * std::pow(T_a, 2), L_lon);
  const double v6 = v5 + a_lon * T_a;

  // Segment s7
  const double s7 = std::min(s6 + T_j * v6 + 0.5 * a_lon * std::pow(T_j, 2), L_lon);

  // ------------------------------------------------------
  // Calculate lateral base points
  // ------------------------------------------------------
  // sign determines the direction of shift
  const double shift_sign = (shift_length > 0.0) ? 1.0 : -1.0;

  // Shift amounts at each segment
  const double l1 = shift_sign * (1.0 / 6.0 * jerk * jerk_time3);
  const double l2 = shift_sign * (1.0 / 6.0 * jerk * jerk_time3 + 0.5 * jerk * accel_time_jerk2 +
                                  0.5 * jerk * accel_time2_jerk);
  const double l3 = shift_sign * (jerk * jerk_time3 + 1.5 * jerk * accel_time_jerk2 +
                                  0.5 * jerk * accel_time2_jerk);  // = l4
  const double l5 = shift_sign * (11.0 / 6.0 * jerk * jerk_time3 + 2.5 * jerk * accel_time_jerk2 +
                                  0.5 * jerk * accel_time2_jerk);
  const double l6 = shift_sign * (11.0 / 6.0 * jerk * jerk_time3 + 3.0 * jerk * accel_time_jerk2 +
                                  jerk * accel_time2_jerk);
  const double l7 = shift_sign * (2.0 * jerk * jerk_time3 + 3.0 * jerk * accel_time_jerk2 +
                                  jerk * accel_time2_jerk);

  // Construct the output vectors
  const std::vector<double> base_lon = {0.0, s1, s2, s3, s5, s6, s7};
  const std::vector<double> base_lat = {0.0, l1, l2, l3, l5, l6, l7};

  return std::make_pair(base_lon, base_lat);
}

std::pair<std::vector<double>, std::vector<double>> get_base_lengths_without_accel_limit(
  const double arc_length, const double shift_length)
{
  // Alias for clarity
  const double total_arc_length = arc_length;
  const double total_shift_length = shift_length;

  // Prepare base longitudinal positions
  const std::vector<double> base_longitudinal = {
    0.0, 0.25 * total_arc_length, 0.75 * total_arc_length, total_arc_length};

  // Prepare base lateral positions
  const std::vector<double> base_lateral = {
    0.0, 1.0 / 12.0 * total_shift_length, 11.0 / 12.0 * total_shift_length, total_shift_length};

  return {base_longitudinal, base_lateral};
}

std::pair<std::vector<double>, std::vector<double>> get_base_lengths_without_accel_limit(
  const double arc_length, const double shift_length)
{
  // Alias for clarity
  const double total_arc_length = arc_length;
  const double total_shift_length = shift_length;

  // Prepare base longitudinal positions
  const std::vector<double> base_longitudinal = {
    0.0, 0.25 * total_arc_length, 0.75 * total_arc_length, total_arc_length};

  // Prepare base lateral positions
  const std::vector<double> base_lateral = {
    0.0, 1.0 / 12.0 * total_shift_length, 11.0 / 12.0 * total_shift_length, total_shift_length};

  return {base_longitudinal, base_lateral};
}

static std::pair<std::vector<double>, std::vector<double>> sanitize_same_base(
  const std::pair<std::vector<double>, std::vector<double>> & lon_lat_original)
{
  static constexpr double k_base_threshold = 1e-3;
  const auto & [lon_original, lat_original] = lon_lat_original;
  std::vector<double> base_lon;
  std::vector<double> base_lat;
  base_lon.push_back(lon_original.front());
  base_lat.push_back(lat_original.front());
  for (const auto [lon, lat] : ranges::views::zip(lon_original, lat_original)) {
    if (std::fabs(base_lon.back() - lon) < k_base_threshold) {
      continue;
    }
    base_lon.push_back(lon);
    base_lat.push_back(lat);
  }
  return {base_lon, base_lat};
}

T compute(const double s) const
{
  const double clamped_s = validate_compute_input(s);
  return compute_impl(clamped_s);
}

double validate_compute_input(const double s) const
{
  constexpr double eps = 1e-5;
  if (eps < start() - s || s - end() > eps) {
    RCLCPP_WARN(
      rclcpp::get_logger("Interpolator"),
      "Input value %f is outside the range of the interpolator [%f, %f].", s, start(), end());
  }
  return std::clamp(s, start(), end());
}

double CubicSpline::compute_impl(const double s) const
{
  const int32_t i = this->get_index(s);
  const double dx = s - this->bases_.at(i);
  return a_(i) + b_(i) * dx + c_(i) * dx * dx + d_(i) * dx * dx * dx;
}

int32_t get_index(const double s, bool end_inclusive = true) const
{
  if (end_inclusive && s == end()) {
    return static_cast<int32_t>(bases_.size()) - 2;
  }
  auto comp = [](const double & a, const double & b) { return a <= b; };
  const auto distance =
    std::distance(bases_.begin(), std::lower_bound(bases_.begin(), bases_.end(), s, comp));
  const int32_t idx = (distance == 0) ? 0 : static_cast<int32_t>(distance) - 1;
  return std::clamp(idx, static_cast<int32_t>(0), static_cast<int32_t>(bases_.size() - 1));
}

