NoNeedToGiveWay::modify_trajectory(
  GiveWay * give_way,
  const experimental::trajectory::Trajectory<
    autoware_internal_planning_msgs::msg::PathPointWithLaneId> & trajectory,
  const OncomingCars & oncoming_cars, const geometry_msgs::msg::Pose & ego_pose,
  const double & ego_speed)
{
  if (ego_speed < 0.1) {
    return trajectory;
  }
  std::optional<CarObject> front_oncoming_car = oncoming_cars.get_front_oncoming_car();
  if (front_oncoming_car.has_value()) {
    bool go_to_shift_mode =
      give_way->decide_ego_stop_pose(ego_pose, ego_speed, *front_oncoming_car);
    if (go_to_shift_mode) {
      give_way->transition_to<ApproachingToShift>();
    }
    return give_way->modify_trajectory_for_waiting(trajectory, ego_pose, true);
  }
  return trajectory;
}

std::optional<CarObject> OncomingCars::get_front_oncoming_car() const
{
  if (oncoming_cars_.empty()) {
    return std::nullopt;
  }

  double min_distance = std::numeric_limits<double>::max();
  std::optional<CarObject> front_oncoming_car;
  for (const auto & oncoming_car : oncoming_cars_) {
    auto center_line = bidirectional_lanelets_->get_center_line();
    double distance = experimental::trajectory::closest(center_line, oncoming_car.get_pose());
    if (distance < min_distance) {
      min_distance = distance;
      front_oncoming_car = oncoming_car;
    }
  }

  return front_oncoming_car;
}

ConnectedBidirectionalLanelets::get_center_line() const
{
  // add cache
  static autoware_utils_system::LRUCache<
    lanelet::ConstLanelets, experimental::trajectory::Trajectory<geometry_msgs::msg::Point>,
    ConstLaneletsHashMap>
    cache(1000);
  if (cache.contains(bidirectional_lanelets_)) {
    return experimental::trajectory::Trajectory<geometry_msgs::msg::Pose>{
      cache.get(bidirectional_lanelets_).value()};
  }
  std::vector<geometry_msgs::msg::Point> center_line;
  for (const auto & lane : bidirectional_lanelets_) {
    for (const auto & point : lane.centerline()) {
      geometry_msgs::msg::Point p;
      p.x = point.x();
      p.y = point.y();
      p.z = point.z();
      center_line.emplace_back(p);
    }
    if (lane != bidirectional_lanelets_.back()) {
      center_line.pop_back();
    }
  }
  auto trajectory =
    experimental::trajectory::Trajectory<geometry_msgs::msg::Point>::Builder{}.build(center_line);

  if (!trajectory) {
