[[nodiscard]] double ConnectedBidirectionalLanelets::average_lane_width() const
{
  static autoware_utils_system::LRUCache<lanelet::ConstLanelets, double, ConstLaneletsHashMap>
    cache(1000);
  if (cache.contains(bidirectional_lanelets_)) {
    return cache.get(bidirectional_lanelets_).value();
  }
  long double length_sum = 0;
  double area_sum = 0;
  for (const auto & lane : bidirectional_lanelets_) {
    length_sum += boost::geometry::length(lane.centerline2d());
    area_sum += boost::geometry::area(lane.polygon2d().basicPolygon());
  }

  auto result = static_cast<double>(area_sum / length_sum);
  cache.put(bidirectional_lanelets_, result);
  return result;
}

double calc_longitudinal_dist_from_jerk(
  const double lateral, const double jerk, const double velocity)
{
  const double j = std::abs(jerk);
  const double l = std::abs(lateral);
  const double v = std::abs(velocity);
  if (j < 1.0e-8) {
    const std::string error_message(
      std::string(__func__) + ": Failed to calculate longitudinal distance due to invalid arg");
    RCLCPP_WARN(get_logger(), "%s", error_message.c_str());
    return 1.0e10;
  }
  return 4.0 * std::pow(0.5 * l / j, 1.0 / 3.0) * v;
}

PointType Trajectory<PointType>::compute(const double s) const
{
  PointType result;
  result.position = BaseClass::compute(s);
  const auto s_clamp = clamp(s);
  // NOTE(soblin): azimuth() should not be used here to serve as interpolator
  result.orientation = orientation_interpolator_->compute(s_clamp);
  return result;
}

T compute(const double s) const
{
  const double clamped_s = validate_compute_input(s);
  return compute_impl(clamped_s);
}

double validate_compute_input(const double s) const
{
  constexpr double eps = 1e-5;
  if (eps < start() - s || s - end() > eps) {
    RCLCPP_WARN(
      rclcpp::get_logger("Interpolator"),
      "Input value %f is outside the range of the interpolator [%f, %f].", s, start(), end());
  }
  return std::clamp(s, start(), end());
}

double CubicSpline::compute_impl(const double s) const
{
  const int32_t i = this->get_index(s);
  const double dx = s - this->bases_.at(i);
  return a_(i) + b_(i) * dx + c_(i) * dx * dx + d_(i) * dx * dx * dx;
}

int32_t get_index(const double s, bool end_inclusive = true) const
{
  if (end_inclusive && s == end()) {
    return static_cast<int32_t>(bases_.size()) - 2;
  }
  auto comp = [](const double & a, const double & b) { return a <= b; };
  const auto distance =
    std::distance(bases_.begin(), std::lower_bound(bases_.begin(), bases_.end(), s, comp));
  const int32_t idx = (distance == 0) ? 0 : static_cast<int32_t>(distance) - 1;
  return std::clamp(idx, static_cast<int32_t>(0), static_cast<int32_t>(bases_.size() - 1));
}

double Trajectory<PointType>::clamp(const double s, bool show_warning) const
{
  constexpr double eps = 1e-5;
  if (show_warning && (s < -eps || s > length() + eps)) {
    RCLCPP_WARN(
      rclcpp::get_logger("Trajectory"), "The arc length %f is out of the trajectory length %f", s,
      length());
  }
  return std::clamp(s, 0.0, length()) + start_;
}

T compute(const double s) const
{
  const double clamped_s = validate_compute_input(s);
  return compute_impl(clamped_s);
}

double CubicSpline::compute_impl(const double s) const
{
  const int32_t i = this->get_index(s);
  const double dx = s - this->bases_.at(i);
  return a_(i) + b_(i) * dx + c_(i) * dx * dx + d_(i) * dx * dx * dx;
}

