double closest(
  const trajectory::Trajectory<TrajectoryPointType> & trajectory, const ArgPointType & point)
{
  std::optional<double> s =
    closest_with_constraint(trajectory, point, [](const TrajectoryPointType &) { return true; });
  assert(s.has_value() && "closest: no closest point found");
  return *s;
}

std::optional<double> closest_with_constraint(
  const trajectory::Trajectory<TrajectoryPointType> & trajectory, const ArgPointType & point,
  Constraint && constraint)
{
  using autoware::experimental::trajectory::detail::to_point;

  return detail::impl::closest_with_constraint_impl(
    [&trajectory](const double & s) {
      const auto point = to_point(trajectory.compute(s));
      Eigen::Vector3d result;
      result << point.x, point.y, point.z;
      return result;
    },
    trajectory.get_underlying_bases(), {to_point(point).x, to_point(point).y, to_point(point).z},
    [constraint = std::forward<Constraint>(constraint), &trajectory](const double & s) {
      return detail::invoke_with_point_or_parameter(
        constraint, s, [&trajectory, &s]() { return trajectory.compute(s); });
    });
}

decltype(auto) invoke_with_point_or_parameter(
  Callable & callable, const double & parameter, PointGetter && point_getter)
{
  using PointType = std::decay_t<std::invoke_result_t<PointGetter &>>;

  if constexpr (std::is_invocable_v<Callable &, const PointType &>) {
    return std::invoke(callable, std::invoke(std::forward<PointGetter>(point_getter)));
  } else if constexpr (std::is_invocable_v<Callable &, const double &>) {
    return std::invoke(callable, parameter);
  } else {
    static_assert(
      always_false_v<Callable>,
      "callable must be callable with either the trajectory point type or double");
  }
}

std::optional<double> closest_with_constraint_impl(
  const std::function<Eigen::Vector3d(const double & s)> & trajectory_compute,
  const std::vector<double> & bases, const Eigen::Vector3d & point,
  const std::function<bool(const double &)> & constraint)
{
  std::vector<double> distances_from_segments;
  std::vector<double> lengths_from_start_points;

  for (size_t i = 1; i < bases.size(); ++i) {
    const Eigen::Vector3d p0 = trajectory_compute(bases.at(i - 1));
    const Eigen::Vector3d p1 = trajectory_compute(bases.at(i));

    const Eigen::Vector3d v = p1 - p0;
    const Eigen::Vector3d w = point - p0;
    const double c1 = w.dot(v);
    const double c2 = v.dot(v);
    const auto length_from_start_point = [&]() {
      if (c2 <= std::numeric_limits<double>::epsilon()) {
        return bases.at(i - 1);
      }
      if (c1 <= 0) {
        return bases.at(i - 1);
      }
      if (c2 <= c1) {
        return bases.at(i);
      }
      return bases.at(i - 1) + c1 / c2 * (p1 - p0).norm();
    }();
    const auto distance_from_segment = [&]() {
      if (c2 <= std::numeric_limits<double>::epsilon()) {
        return (point - p0).norm();
      }
      if (c1 <= 0) {
        return (point - p0).norm();
      }
      if (c2 <= c1) {
        return (point - p1).norm();
      }
      return (point - (p0 + (c1 / c2) * v)).norm();
    }();
    if (constraint(length_from_start_point)) {
      distances_from_segments.push_back(distance_from_segment);
      lengths_from_start_points.push_back(length_from_start_point);
    }
  }
  if (distances_from_segments.empty()) {
    return std::nullopt;
  }

  auto min_it = std::min_element(distances_from_segments.begin(), distances_from_segments.end());

  return lengths_from_start_points.at(std::distance(distances_from_segments.begin(), min_it));
}

detail::InterpolatedArray<double> & longitudinal_velocity_mps()
{
  return *longitudinal_velocity_mps_;
}

std::vector<PointType> Trajectory<PointType>::restore() const
{
  std::vector<PointType> points;
  const auto bases = get_underlying_bases();
  points.reserve(bases.size());
  for (const auto & s : bases) {
    points.push_back(compute(s));
  }
  return points;
}

std::vector<double> Trajectory<PointType>::get_underlying_bases() const
{
  auto bases = detail::crop_bases(bases_, start_, end_);

  std::transform(
    bases.begin(), bases.end(), bases.begin(), [this](const double & s) { return s - start_; });
  return bases;
}

std::vector<double> crop_bases(const std::vector<double> & x, const double start, const double end)
{
  std::vector<double> result;

  // Add start point if it's not already in x
  if (std::find(x.begin(), x.end(), start) == x.end()) {
    result.push_back(start);
  }

  // Copy all points within the range [start, end]
  std::copy_if(x.begin(), x.end(), std::back_inserter(result), [start, end](double i) {
    return i >= start && i <= end;
  });

  // Add end point if it's not already in x
  if (std::find(x.begin(), x.end(), end) == x.end()) {
    result.push_back(end);
  }

  return result;
}
